const ensureTenThingsToDo = (city: City): City => {
  const currentThingsToDo = city.thingsToDo ?? [];

  if (currentThingsToDo.length >= 10) {
    return city;
  }

  const additions = phaseThreeThingsToDoAdditions[city.slug] ?? [];
  const existingNames = new Set(currentThingsToDo.map((thing) => thing.name));
  const icons = ['*', '*', '*', '*'];
  const durations = ['1-2 hrs', '2-3 hrs', 'Half day', '2-4 hrs'];
  const categories = ['Cultural', 'Local', 'Scenic', 'Hidden gem'];
  const appended = additions
    .filter((name) => !existingNames.has(name))
    .slice(0, Math.max(0, 10 - currentThingsToDo.length))
    .map((name, index) => ({
      name,
      description: `${name} rounds out a ${city.name} itinerary with a worthwhile extra stop. Pair it with a nearby meal, viewpoint, market, or neighbourhood walk so the day feels full without becoming rushed.`,
      icon: icons[index % icons.length],
      duration: durations[index % durations.length],
      category: categories[index % categories.length],
    }));

  if (appended.length === 0) {
    return city;
  }

  return {
    ...city,
    thingsToDo: [...currentThingsToDo, ...appended],
  };
};

