    thingsToDo: [
      { name: 'Ancient Town Evening Walk', description: "Hoi An's Ancient Town is most magical after 5pm when lanterns are lit and cars are banned. Walk the Japanese Covered Bridge (1593), the Fujian Assembly Hall, riverside promenade, and An Hoi Island where coloured silk lanterns are sold from floating boats.", icon: '🏮', duration: '2–3 hrs', category: 'Cultural' },
      { name: 'Cao Lau & Banh Mi Phuong', description: "Hoi An has the most distinctive food in Vietnam. Cao lau (a noodle dish made only with water from the town's ancient well), White Rose dumplings (Banh Vac), and the Banh Mi sandwich perfected at Banh Mi Phuong — called the world's best by Anthony Bourdain.", icon: '🍜', duration: '2 hrs', category: 'Culinary' },
      { name: 'Custom Tailor Visit', description: "Hoi An has over 400 tailors who can produce a bespoke suit, ao dai, or dress in 24–48 hours at a fraction of Western prices. Yaly Couture and A Dong Silk are the most reputable. Order early in your stay for fitting time.", icon: '✂️', duration: '1–2 hrs', category: 'Shopping' },
      { name: 'Basket Boat Tour — Cam Thanh Village', description: "5km from the Ancient Town, the Cam Thanh coconut palm forest is explored on traditional round wicker basket boats — the boatman spins the coracle with astonishing skill. Crab fishing, folk music, and a coconut wine tasting round out the 2-hour experience.", icon: '🛶', duration: '2–3 hrs', category: 'Adventure' },
      { name: 'My Son Hindu Sanctuary Day Trip', description: "40km west of Hoi An, My Son is a UNESCO World Heritage cluster of 4th–14th century Cham Hindu temples — the greatest monument of the Cham civilisation. Best visited early (8am) before tour groups arrive and the heat builds.", icon: '🛕', duration: 'Half day', category: 'Historical' },
      { name: 'Cooking Class with Market Visit', description: "Hoi An cooking classes consistently rank among the best in Southeast Asia — most start with a guided Thu Bon Market walk to select fresh ingredients, then teach cao lau, white rose, and Vietnamese crepes (banh xeo) in riverside kitchens.", icon: '👨‍🍳', duration: '4–5 hrs', category: 'Culinary' },
      { name: 'An Bang Beach', description: 'A relaxed white-sand beach 3km from the Ancient Town — beach bars on stilts, sun loungers, and fresh seafood barbecues right on the sand. Best in the late afternoon as the sun lowers.', icon: '🏖️', duration: 'Half day', category: 'Beach' },
      { name: 'Tra Que Vegetable Village Bike Ride', description: 'Cycle through rice paddies and herb gardens to Tra Que, a centuries-old organic vegetable village — try a hands-on farming experience, planting and watering alongside local farmers.', icon: '🚲', duration: '2–3 hrs', category: 'Cultural' },
      { name: 'Lantern-Making Workshop', description: "Learn to fold and assemble Hoi An's iconic silk lanterns in a small riverside workshop — a relaxed, hands-on craft session and a lantern of your own to take home.", icon: '🏮', duration: '1.5 hrs', category: 'Cultural' },
      { name: 'Cham Islands Snorkelling Trip', description: 'A boat trip to the Cham Islands marine protected area off the coast — clear water, coral reefs, and a fishing village, with lunch of freshly caught seafood.', icon: '🤿', duration: 'Full day', category: 'Adventure' },
    ],
